insert into CHB_PRD_RATE(SEQNO, PROD_ID, FPROD_ID, IS_LAY, CHANGE_DATE, CASHMDATE, PROFIT_TYPE, CHANGE_TYPE, PROD_YIELD, PROD_BENCHMARK_RATE, UNIT_VALUE_TOTAL, UNIT_VALUE, SEVEN_DAY_RATE, ORG_CODE, DEPT_CODE, STATUS, REV_DATE, DATA_SOURCE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, REMARK, CCY) select SEQNO, PROD_ID, FPROD_ID, IS_LAY, CHANGE_DATE, CASHMDATE, PROFIT_TYPE, CHANGE_TYPE, PROD_YIELD, PROD_BENCHMARK_RATE, UNIT_VALUE_TOTAL, UNIT_VALUE, SEVEN_DAY_RATE, ORG_CODE, DEPT_CODE, STATUS, REV_DATE, DATA_SOURCE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, REMARK, CCY from ( select TEMP.SEQNO, TEMP.PROD_ID, TEMP.FPROD_ID, TEMP.IS_LAY, TEMP.CHANGE_DATE, TEMP.CASHMDATE, TEMP.PROFIT_TYPE, TEMP.CHANGE_TYPE, TEMP.PROD_YIELD, TEMP.PROD_BENCHMARK_RATE, TEMP.UNIT_VALUE_TOTAL, TEMP.UNIT_VALUE, TEMP.SEVEN_DAY_RATE, TEMP.ORG_CODE, TEMP.DEPT_CODE, TEMP.STATUS, TEMP.REV_DATE, TEMP.DATA_SOURCE, TEMP.UPDATE_USER, TEMP.UPDATE_TIME, TEMP.CREATE_USER, TEMP.CREATE_TIME, TEMP.REMARK, TEMP.CCY from (
SELECT #{item.seqno,jdbcType=CHAR} SEQNO, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.isLay,jdbcType=VARCHAR} IS_LAY, #{item.changeDate,jdbcType=DATE} CHANGE_DATE, #{item.cashmdate,jdbcType=DATE} CASHMDATE, #{item.profitType,jdbcType=VARCHAR} PROFIT_TYPE, #{item.changeType,jdbcType=VARCHAR} CHANGE_TYPE, #{item.prodYield,jdbcType=DECIMAL} PROD_YIELD, #{item.prodBenchmarkRate,jdbcType=DECIMAL} PROD_BENCHMARK_RATE, #{item.unitValueTotal,jdbcType=DECIMAL} UNIT_VALUE_TOTAL, #{item.unitValue,jdbcType=DECIMAL} UNIT_VALUE, #{item.sevenDayRate,jdbcType=DECIMAL} SEVEN_DAY_RATE, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.revDate,jdbcType=DATE} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, now() UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, now() CREATE_TIME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.ccy,jdbcType=VARCHAR} CCY FROM DUAL
) TEMP where not EXISTS (select 1 from CHB_PRD_RATE CII where CII.PROD_ID = TEMP.PROD_ID AND DATE_FORMAT(CII.CHANGE_DATE,'%Y-%m-%d') = DATE_FORMAT(TEMP.CHANGE_DATE,'%Y-%m-%d') AND CII.CHANGE_TYPE = TEMP.CHANGE_TYPE) ) de ; UPDATE CHB_PRD_DEAL as A, ( select SEQNO, FPROD_IDD, IS_LAY, CASHMDATE, PROFIT_TYPE, PROD_YIELD, PROD_BENCHMARK_RATE, UNIT_VALUE_TOTAL, UNIT_VALUE, SEVEN_DAY_RATE, ORG_CODE, DEPT_CODE, STATUSS, REV_DATEE, DATA_SOURCE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, REMARK, CCY from ( select TEMP.SEQNO, TEMP.FPROD_IDD, TEMP.IS_LAY, TEMP.CASHMDATE, TEMP.PROFIT_TYPE, TEMP.PROD_YIELD, TEMP.PROD_BENCHMARK_RATE, TEMP.UNIT_VALUE_TOTAL, TEMP.UNIT_VALUE, TEMP.SEVEN_DAY_RATE, TEMP.ORG_CODE, TEMP.DEPT_CODE, TEMP.STATUSS, TEMP.REV_DATEE, TEMP.DATA_SOURCE, TEMP.UPDATE_USER, TEMP.UPDATE_TIME, TEMP.CREATE_USER, TEMP.CREATE_TIME, TEMP.REMARK, TEMP.CCY from (
SELECT #{item.seqno,jdbcType=CHAR} SEQNO, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.isLay,jdbcType=VARCHAR} IS_LAY, #{item.changeDate,jdbcType=DATE} CHANGE_DATE, #{item.cashmdate,jdbcType=DATE} CASHMDATE, #{item.profitType,jdbcType=VARCHAR} PROFIT_TYPE, #{item.changeType,jdbcType=VARCHAR} CHANGE_TYPE, #{item.prodYield,jdbcType=DECIMAL} PROD_YIELD, #{item.prodBenchmarkRate,jdbcType=DECIMAL} PROD_BENCHMARK_RATE, #{item.unitValueTotal,jdbcType=DECIMAL} UNIT_VALUE_TOTAL, #{item.unitValue,jdbcType=DECIMAL} UNIT_VALUE, #{item.sevenDayRate,jdbcType=DECIMAL} SEVEN_DAY_RATE, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.revDate,jdbcType=DATE} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, now() UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, now() CREATE_TIME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.ccy,jdbcType=VARCHAR} CCY FROM DUAL
) TEMP ) de ) AS B set A.SEQNO = B.SEQNO, A.FPROD_ID = B.FPROD_ID, A.IS_LAY = B.IS_LAY, A.CASHMDATE = B.CASHMDATE, A.PROFIT_TYPE = B.PROFIT_TYPE, A.PROD_YIELD = B.PROD_YIELD, A.PROD_BENCHMARK_RATE = B.PROD_BENCHMARK_RATE, A.UNIT_VALUE_TOTAL = B.UNIT_VALUE_TOTAL, A.UNIT_VALUE = B.UNIT_VALUE, A.SEVEN_DAY_RATE = B.SEVEN_DAY_RATE, A.ORG_CODE = B.ORG_CODE, A.DEPT_CODE = B.DEPT_CODE, A.STATUS = B.STATUS, A.REV_DATE = B.REV_DATE, A.DATA_SOURCE = B.DATA_SOURCE, A.UPDATE_USER= B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME, A.CREATE_USER = B.CREATE_USER, A.CREATE_TIME = B.CREATE_TIME, A.REMARK = B.REMARK, A.CCY = B.CCY where A.PROD_ID = B.PROD_ID AND DATE_FORMAT(A.CHANGE_DATE,'%Y-%m-%d') = DATE_FORMAT(B.CHANGE_DATE,'%Y-%m-%d') AND A.CHANGE_TYPE = B.CHANGE_TYPE ;
